import java.util.*;

class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        List<Integer> vals = new ArrayList<>();
        for (ListNode p = head; p != null; p = p.next) vals.add(p.val);
        int n = vals.size();

        // 只有凑满 k 个的组才反转，尾巴保持原样
        for (int g = 0; g * k + k <= n; g++) {
            int i = g * k, j = g * k + k - 1;
            while (i < j) {
                int t = vals.get(i);
                vals.set(i, vals.get(j));
                vals.set(j, t);
                i++;
                j--;
            }
        }

        int idx = 0;
        for (ListNode p = head; p != null; p = p.next) p.val = vals.get(idx++);
        return head;
    }
}

class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode groupPrev = dummy;

        while (true) {
            // 1. 先走 k 步找组尾，走不满说明剩余不足 k，直接结束
            ListNode groupEnd = groupPrev;
            for (int i = 0; i < k; i++) {
                groupEnd = groupEnd.next;
                if (groupEnd == null) return dummy.next;
            }
            ListNode groupNext = groupEnd.next;

            // 2. 反转这一段，每次反转后立即前移
            ListNode prev = groupNext, curr = groupPrev.next;
            for (int i = 0; i < k; i++) {
                ListNode tmp = curr.next;
                curr.next = prev;
                prev = curr;
                curr = tmp;
            }

            // 3. 重连：前驱接新头，原头（现尾）已指向 groupNext
            ListNode oldHead = groupPrev.next;
            groupPrev.next = groupEnd;
            groupPrev = oldHead;
        }
    }
}

class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode groupPrev = dummy;

        while (groupPrev.next != null) {
            // 1. 切：走 k 步找组尾
            ListNode groupEnd = groupPrev;
            for (int i = 0; i < k; i++) {
                groupEnd = groupEnd.next;
                if (groupEnd == null) return dummy.next;   // 不足 k 个
            }
            ListNode after = groupEnd.next;
            groupEnd.next = null;          // 把这一组彻底摘下来

            // 2. 反：复用第 206 题的标准反转
            ListNode oldHead = groupPrev.next;
            ListNode newHead = reverse(oldHead);

            // 3. 接：前接新头，原头（现组尾）接后半段
            groupPrev.next = newHead;
            oldHead.next = after;
            groupPrev = oldHead;
        }
        return dummy.next;
    }

    private ListNode reverse(ListNode head) {
        ListNode prev = null, curr = head;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
}
